  ctx.store.update({ cmp: [...ids, selected].join(',') });
  setStatus(status, `„${record?.title ?? selected}“ gemerkt (${ids.length + 1} von ${MAX_PINNED}).`, 'success');
}

function remove(id) {
  const ids = pinnedIds().filter((entry) => entry !== id);
