/**
 * Where keyboard focus goes when the panel closes.
 *
 * The element that opened the panel — a result row, a map pin, an “Auswählen”
 * button — is the best place to come back to, but it is not always there: a
 * `?sel=` deep link has no opener at all, the two filter actions rebuild the
 * list *before* the panel closes, and the browser's back button closes the
 * panel from the URL. Focusing a removed or non-focusable node leaves focus on
 * `<body>`, which drops a keyboard user at the start of the document; so the
 * row of the record that was just open is the next stop and the main landmark
 * is the last one. Nothing scrolls the page (`preventScroll`): the panel must
 * not move the visitor, the same rule the map selection follows on phones.
 */
function restoreFocus(recordId) {
  const candidates = [opener];
  if (recordId) candidates.push(qs(`#result-list button[data-record-id="${recordId}"]`));
  candidates.push(qs('#main'));
  opener = null;
  for (const target of candidates) {
    if (!target || !target.isConnected || !target.getClientRects().length) continue;
    target.focus({ preventScroll: true });
    if (document.activeElement === target) return target;
  }
  return null;
}

function close() {
  if (panel.hidden) return;
  const recordId = current?.id ?? '';
  viewer?.destroy();
  viewer = null;
  stripObserver?.disconnect();
  stripObserver = null;
  page = 0;
  // A closed panel must not leave a sheet number or a viewer region behind in
  // the shared URL.
  if (ctx.store.getState().sheet !== 1 || ctx.store.getState().vv) ctx.store.update({ sheet: 1, vv: '' });
  panel.hidden = true;
  if (scrim) scrim.hidden = true;
  panel.setAttribute('aria-modal', 'false');
  document.body.classList.remove('has-detail');
  current = null;
  body.replaceChildren();
  restoreFocus(recordId);
  ctx.bus.emit('record:deselected', {});
}

