function restoreFocus(recordId) {
  const candidates = [opener];
  if (recordId) candidates.push(qs(`#result-list button[data-record-id="${recordId}"]`));
  candidates.push(qs('#main'));
  opener = null;
  for (const target of candidates) {
    // `<body>` is the default active element, so `document.activeElement ===
    // body` cannot tell “focus() worked” from “nothing happened” — a deep link
    // opens the panel with `body` as its opener and used to end the search
    // here, which is exactly the state this helper exists to avoid.
    if (!target || target === document.body || target === document.documentElement) continue;
    if (!target.isConnected || !target.getClientRects().length) continue;
    target.focus({ preventScroll: true });
    if (document.activeElement === target) return target;
  }
  return null;
}

